={{ (() => {
  const body = $('Records Webhook').first().json.body;
  const MAX_RECORDS = 100, MAX_CHARS = 10000;
  const errors = {};
  let input = [];
  if (body && Array.isArray(body.records)) input = body.records;
  else if (body && typeof body === 'object' && !Array.isArray(body) && Object.keys(body).length) input = [body];
  if (input.length === 0) errors.records = 'Send {"records": [...]} with at least one record';
  if (input.length > MAX_RECORDS) errors.records = 'Max ' + MAX_RECORDS + ' records per request (got ' + input.length + ')';

  const batchId = 'REV-' + $now.toFormat('yyyyMMdd-HHmmss') + '-' + $execution.id;
  const s = v => (v === undefined || v === null) ? '' : String(v).trim();
  const records = [];
  input.slice(0, MAX_RECORDS).forEach((r, i) => {
    const at = 'records[' + i + ']';
    if (!r || typeof r !== 'object' || Array.isArray(r)) { errors[at] = 'Must be an object'; return; }
    const content = r.content ?? r.text ?? r.description ?? r.message;
    if (typeof content !== 'string' || !content.trim()) { errors[at + '.content'] = 'Required non-empty string'; return; }
    if (content.length > MAX_CHARS) { errors[at + '.content'] = 'Max ' + MAX_CHARS + ' characters'; return; }
    const amount = typeof r.amount === 'string' && r.amount.trim() !== '' ? Number(r.amount) : r.amount;
    records.push({
      batch_id: batchId,
      record_id: s(r.id) || (batchId + '-' + (i + 1)),
      title: s(r.title ?? r.subject).slice(0, 200),
      content: content.trim(),
      customer_email: s(r.customer_email ?? r.email).toLowerCase(),
      amount: typeof amount === 'number' && Number.isFinite(amount) ? amount : null,
      currency: s(r.currency),
      source: s(r.source ?? body.source) || 'api',
      created_at: s(r.created_at),
      metadata: (r.metadata && typeof r.metadata === 'object') ? r.metadata : {}
    });
  });
  const valid = Object.keys(errors).length === 0;
  return { valid, errors, batch_id: batchId, count: records.length, records: valid ? records : [] };
})() }}

={{ (() => {
  const cfg = $('Config').first().json;
  const text = (String($json.title ?? '') + ' ' + String($json.content ?? '')).toLowerCase();
  const keywords = String(cfg.risk_keywords ?? '').split(',').map(k => k.trim().toLowerCase()).filter(Boolean);
  const hits = keywords.filter(k => text.includes(k));
  const flags = [];
  let force = false;
  if (hits.length) { flags.push('risk keywords: ' + hits.join(', ')); force = true; }
  if (typeof $json.amount === 'number' && $json.amount >= cfg.amount_threshold) {
    flags.push('amount ' + $json.amount + ' >= ' + cfg.amount_threshold); force = true;
  }
  if (!$json.customer_email) flags.push('no customer email');
  return { flags, force_review: force };
})() }}

