=Review this record and decide whether a human must look at it.

Record (JSON):
{{ JSON.stringify($json.record, null, 2) }}

Hard-rule flags computed by code (facts): {{ $json.rules.flags.length ? $json.rules.flags.join('; ') : 'none' }}

assignments.value:
={{ (() => {
  const rules = $('Apply Hard Rules').item.json.rules;
  const cfg = $('Config').first().json;
  const o = $json.output;
  const aiOk = !!o && typeof o.needs_human_review === 'boolean';
  let needs, by, reason;
  if (!aiOk) {
    needs = true; by = 'fail_safe';
    reason = 'Automated review failed: ' + String($json.error ?? 'no structured output').slice(0, 200);
  } else if (rules.force_review) {
    needs = true; by = 'hard_rule';
    reason = rules.flags.join('; ') + ' | AI: ' + o.reason;
  } else if (o.needs_human_review) {
    needs = true; by = 'ai'; reason = o.reason;
  } else if (o.confidence < cfg.confidence_threshold) {
    needs = true; by = 'low_confidence';
    reason = 'AI suggested auto-clear with low confidence (' + o.confidence + ' < ' + cfg.confidence_threshold + '): ' + o.reason;
  } else {
    needs = false; by = 'ai'; reason = o.reason;
  }
  const basePriority = aiOk ? o.priority : 'high';
  return {
    needs_human_review: needs,
    decided_by: by,
    reason: reason.slice(0, 500),
    priority: needs && basePriority === 'low' ? 'medium' : basePriority,
    category: aiOk ? o.category : 'unknown',
    confidence: aiOk ? o.confidence : null,
    suggested_action: aiOk ? o.suggested_action : 'Review manually: the automated review failed.',
    ai_status: aiOk ? 'OK' : 'FAILED'
  };
})() }}

={{ (() => {
  const f = $('Finalize Decision').item.json;
  const r = f.record, d = f.decision;
  const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const icon = { critical: '🚨', high: '🔴', medium: '🟠', low: '🟢' }[d.priority] || '⚪';
  const excerpt = esc(r.content).slice(0, 700).split('\n').map(l => '>' + l).join('\n');
  return [
    { type: 'header', text: { type: 'plain_text', text: icon + ' Needs review: ' + String(r.title || r.record_id).slice(0, 120), emoji: true } },
    { type: 'section', fields: [
      { type: 'mrkdwn', text: '*Priority*\n' + d.priority },
      { type: 'mrkdwn', text: '*Category*\n' + d.category },
      { type: 'mrkdwn', text: '*Decided by*\n' + d.decided_by },
      { type: 'mrkdwn', text: '*Confidence*\n' + (d.confidence ?? 'n/a') },
      { type: 'mrkdwn', text: '*Customer*\n' + (r.customer_email ? esc(r.customer_email) : '_unknown_') },
      { type: 'mrkdwn', text: '*Amount*\n' + (r.amount !== null && r.amount !== undefined ? r.amount + ' ' + esc(r.currency) : '-') }
    ] },
    { type: 'section', text: { type: 'mrkdwn', text: '*Why:* ' + esc(d.reason) } },
    { type: 'section', text: { type: 'mrkdwn', text: '*Suggested action:* ' + esc(d.suggested_action) } },
    { type: 'section', text: { type: 'mrkdwn', text: excerpt || '_empty_' } },
    { type: 'context', elements: [ { type: 'mrkdwn', text: 'Record `' + esc(r.record_id) + '` · Batch `' + esc(r.batch_id) + '` · Source ' + esc(r.source) + (f.rules.flags.length ? ' · Flags: ' + esc(f.rules.flags.join('; ')) : '') } ] }
  ];
})() }}

={{ (() => {
  const t = $('On Workflow Error').first().json;
  const msg = t.execution?.error?.message ?? t.trigger?.error?.message ?? '';
  if (msg.includes('[CRITICAL]')) return 'CRITICAL';
  if (msg.includes('[WARNING]')) return 'WARNING';
  return 'ERROR';
})() }}

